  "brain.py": "\"\"\"The brain - one Neuron, one Receptor. `python brain.py` runs it.\n\n    python brain.py\n    open http://127.0.0.1:8000\n\nLayout\n------\n    neurons/assistant.py the one Neuron - Axon.huggingface(), no config module\n    receptors/chat.py    the one Receptor - a ChatReceptor addressing it\n    brain.py             deployment: which node hosts what\n\nOne node, one Dendrite: the worker hosts the Axon, the edge hosts the\nReceptor. A Receptor may only mount on an orchestrator-role Dendrite (it\noriginates TASKs), so the two are always separate nodes even in an example\nthis small.\n\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\nimport contextlib\nimport os\nimport signal\n\nfrom cosmonapse import Dendrite, MemorySynapse, connect_synapse, run_brain\n\nfrom neurons import assistant\nfrom receptors import chat\n\nNAMESPACE = \"simple-chat-hf\"\nSYNAPSE_URL = os.environ.get(\"SYNAPSE_URL\", \"\")   # unset -> in-process bus\n\n\ndef build_worker(synapse) -> Dendrite:\n    \"\"\"Hosts the assistant Axon - services the TASK a turn dispatches.\"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"worker\", role=\"worker\")\n    node.attach_axon(assistant.AXON)\n    return node\n\n\ndef build_edge(synapse) -> Dendrite:\n    \"\"\"Hosts the chat Receptor - the only node allowed to dispatch.\"\"\"\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"edge\", role=\"orchestrator\", heartbeat_s=0)\n    node.attach_receptor(chat.RECEPTOR)\n    return node\n\n\ndef _stop_on_signals() -> None:\n    task = asyncio.current_task()\n    loop = asyncio.get_running_loop()\n    for sig in (signal.SIGINT, signal.SIGTERM):\n        with contextlib.suppress(NotImplementedError, AttributeError):\n            loop.add_signal_handler(sig, task.cancel)\n\n\nasync def main() -> int:\n    _stop_on_signals()\n    if SYNAPSE_URL:\n        synapse = await connect_synapse(SYNAPSE_URL)\n    else:\n        synapse = MemorySynapse()  # in-process bus - no broker, no setup\n        await synapse.connect()\n    try:\n        return await run_brain(build_worker(synapse), build_edge(synapse))\n    except asyncio.CancelledError:\n        return 0\n    finally:\n        await synapse.close()\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(asyncio.run(main()))\n    except KeyboardInterrupt:\n        raise SystemExit(130)\n",
  "neurons/assistant.py": "\"\"\"assistant - the one Neuron.\n\n``Axon.huggingface()`` pairs an Axon straight with a HuggingFace-backed\nNeuron - no hand-written wrapper function, no shared config module.\napi_key is a placeholder: replace \"hf_dummy_token\" with your Hugging Face\ntoken to run it. MODEL can still be set in the environment or a .env file.\n\"\"\"\nimport os\nfrom pathlib import Path\n\nfrom dotenv import load_dotenv\n\nfrom cosmonapse import Axon\n\nload_dotenv()                                                  # ./.env\nload_dotenv(Path(__file__).resolve().parents[2] / \".env\")      # cosmonapse-examples/.env\n\nAXON = Axon.huggingface(\n    neuron_id=\"assistant\",\n    endpoint=\"https://router.huggingface.co\",\n    model=os.environ.get(\"MODEL\", \"meta-llama/Llama-3.1-8B-Instruct\"),\n    api_key=\"hf_dummy_token\",\n    use_chat_api=True,\n    max_new_tokens=400,\n    capabilities=[\"chat\", \"text-generation\"],\n)\n\n\n@AXON.before_task\ndef fold_history(input_data: dict) -> dict:\n    \"\"\"ChatReceptor rides prior turns in as history=[{role, content}, ...];\n    the HF Neuron only ever reads prompt/messages, so fold them in here\n    before the Neuron runs.\"\"\"\n    turns = input_data.get(\"history\") or []\n    if not turns:\n        return input_data\n    transcript = \"\\n\".join(f\"{t['role']}: {t['content']}\" for t in turns)\n    prompt = input_data.get(\"prompt\", \"\")\n    return {**input_data, \"prompt\": f\"{transcript}\\nuser: {prompt}\"}\n",
